      },
      {
        "biomarker": "vitamin_d",
        "value": 15.22,
        "unit": "ng/mL",
        "flag": "low",
        "comment": "Below the reference low of 30.0 ng/mL; may suggest low vitamin D status. Clinical correlation and consideration of supplementation advised."
      }
    ],
    "lifestyle_restrictions": [
      "All diet plans must be Jain-compatible and strictly peanut-free (documented peanut allergy)."
    ],
    "recommended_followups": [
      "Cardiology review of lipid profile (LDL 150.81 mg/dL, triglycerides 212.57 mg/dL).",
      "General physician review of vitamin D 15.22 ng/mL; consider supplementation and repeat vitamin D testing.",
      "Repeat lipid panel after dietary and lifestyle modification to track response.",
      "Dietician/lifestyle coach to build a Jain-compatible, peanut-free diet plan as requested by the member."
    ]
  }
}

response:
{
  "focus_areas": [
    "High triglycerides",
    "High LDL cholesterol",
    "Low vitamin D",
    "Jain-compatible, peanut-free eating"
  ],
  "diet_recommendations": [
    {
      "item": "Breakfast (7:30–8:30 am): 1 bowl (about 150 g cooked) of oats or dalia porridge made with water or skimmed milk, topped with 1 tbsp ground flaxseed and 5–6 soaked almonds (ensure no peanut cross-contamination). Do not add honey or sugar; a pinch of cinnamon is fine.",
      "rationale": "Soluble fibre from oats/dalia and omega-3 fats from flaxseed help lower triglycerides; almonds give healthy fats without peanuts.",
      "linked_biomarker": "triglycerides"
    },
    {
      "item": "Lunch (1:00–2:00 pm): 2 jowar or bajra rotis + 1 katori (150 g cooked) rajma, chana, or dal + 1 katori seasonal sabzi (lauki, tinda, bhindi, or palak) cooked with 1 tsp mustard oil + a small salad of cucumber, tomato, and coriander. Avoid potato, onion, garlic, and ginger.",
      "rationale": "Soluble fibre from legumes and whole millets helps bind cholesterol and lower LDL; mustard oil provides unsaturated fats instead of saturated fats.",
      "linked_biomarker": "ldl"
    },
    {
      "item": "Mid-afternoon snack (4:00–4:30 pm): 1 cup steamed moong sprouts seasoned with lemon, cumin, and black pepper, or 1 small apple/guava + 1 cup unsweetened green tea.",
      "rationale": "Replacing fried snacks with fibre-rich sprouts or fruit reduces refined carbohydrate and fat intake, which helps lower triglycerides.",
      "linked_biomarker": "triglycerides"
    },
    {
      "item": "Dinner (7:30–8:30 pm): 1 bowl (about 150 g cooked) vegetable khichdi made with brown rice and moong dal, using lauki, tomato, and spinach (no onion, garlic, ginger, or potato) + 1 katori curd or cucumber salad.",
      "rationale": "Whole-grain and legume fibre at dinner supports LDL reduction and keeps refined carbohydrate intake low.",
      "linked_biomarker": "ldl"
    },
    {
      "item": "Daily vitamin D routine: spend 15–20 minutes in direct mid-morning sunlight (around 10–11 am) on face and arms, 4–5 days a week, without sunscreen. Also include 1 cup fortified milk or 1 katori curd with meals.",
      "rationale": "Sunlight is the main natural source of vitamin D, and fortified dairy adds a small amount. The doctor has advised considering supplementation—ask your FOXO doctor about vitamin D testing and supplement advice.",
      "linked_biomarker": "vitamin_d"
    }
  ],
  "foods_to_avoid": [
    "Peanuts, peanut oil, peanut butter, peanut chutney, and any packaged food labelled 'may contain peanuts' (peanut allergy).",
    "Onion, garlic, potato, carrot, beetroot, radish, ginger, and other root vegetables (Jain diet).",
    "Honey, eggs, meat, fish, and seafood (Jain diet).",
    "Deep-fried snacks such as samosa, pakora, puri, and fried namkeen.",
    "Sweets, jaggery, sugary drinks, fruit juices, and sweetened tea or coffee (to lower triglycerides).",
    "Refined flour (maida) products like white bread, naan, biscuits, cakes, and pastries (to lower LDL and triglycerides).",
    "Excess ghee, butter, coconut oil, cream, and full-fat paneer (to lower LDL).",
    "Packaged and processed foods high in salt and trans fats."
  ],
  "activity": "Walk briskly for 30–40 minutes, 5 days a week (start with 20 minutes if needed); add 10 minutes of gentle stretching or yoga daily. Follow your doctor's advice if you feel any discomfort.",
  "sleep": "Aim for 7–8 hours of sleep with a fixed bedtime and wake-up time; avoid screens 1 hour before bed and keep the room dark and cool.",
  "retest_in_weeks": 12
}
